<script setup lang="ts">
import { computed } from 'vue'
import { useCharactersStore } from '../../stores/characters'
import { pretty } from '../../lib/character-sheet'
const c = computed(() => useCharactersStore().current!)
const sourceLink = computed(()=> /^https:\/\/www\.dungeonmastersvault\.com\/pages\/dnd\/5e\/characters\/\d+$/.test(c.value.externalImport?.sourceUrl??'') ? c.value.externalImport!.sourceUrl : '')
function download(){const original=c.value.externalImport?.source;if(!original)return;let format='edn';try{JSON.parse(original);format='json'}catch{/* Preserve the original format. */}const url=URL.createObjectURL(new Blob([original],{type:`application/${format};charset=utf-8`}));const a=document.createElement('a');a.href=url;a.download=`${c.value.meta.name.replace(/[^a-z0-9]+/gi,'-')}-original.${format}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
</script>
<template><div class="sheet-section-stack"><header class="sheet-section-title"><p class="sheet-eyebrow">THE PERSON BEHIND THE NUMBERS</p><h2>Bio & notes</h2><p>Update your story and notes in Edit character.</p></header><section class="sheet-panel"><h3>Identity</h3><dl class="sheet-key-values"><div><dt>Background</dt><dd>{{c.meta.background||'—'}}</dd></div><div><dt>Alignment</dt><dd>{{c.meta.alignment||'—'}}</dd></div></dl></section><div class="sheet-bio-grid"><section v-for="(value,key) in c.personality" :key="key" class="sheet-panel"><h3>{{pretty(key)}}</h3><p class="sheet-prose">{{value||'Nothing recorded yet.'}}</p></section></div><section v-if="c.externalImport" class="sheet-panel"><h3>Original character source</h3><div class="sheet-filter-buttons"><a v-if="sourceLink" :href="sourceLink" target="_blank" rel="noopener noreferrer" class="sheet-button">Open original character</a><button class="sheet-button" @click="download">Download original choices</button></div><details v-if="c.externalImport.warnings.length"><summary>Import review notes</summary><p v-for="warning in c.externalImport.warnings" :key="warning" class="sheet-prose">{{warning}}</p></details></section></div></template>
